replace_once('backend/tests/test_importer.py', '    def test_import_preview_uses_regex_chapter_boundaries_without_llm(self):\n', '    def test_import_file_detects_gb18030(self):\n        project_id = self.create_project("GB18030 Project")\n        text = "第一章 风起\\n陆糖看见归墟阵重新亮起。"\n\n        response = self.client.post(\n            f"{API_PREFIX}/projects/{project_id}/import/file",\n            files={"file": ("gb.txt", text.encode("gb18030"), "text/plain")},\n        )\n\n        self.assertEqual(response.status_code, 200)\n        data = response.json()["data"]\n        self.assertEqual(data["encoding"], "GB18030")\n        self.assertEqual(data["text"], text)\n        self.assertNotIn("\\ufffd", data["text"])\n\n    def test_import_file_detects_utf16le_without_bom(self):\n        project_id = self.create_project("UTF16 Project")\n        text = "第一章 风起\\n这是 UTF-16LE 正文。"\n\n        response = self.client.post(\n            f"{API_PREFIX}/projects/{project_id}/import/file",\n            files={"file": ("utf16.txt", text.encode("utf-16-le"), "text/plain")},\n        )\n\n        self.assertEqual(response.status_code, 200)\n        data = response.json()["data"]\n        self.assertEqual(data["encoding"], "UTF-16LE")\n        self.assertEqual(data["text"], text)\n\n    def test_atomic_project_file_import_creates_project_and_all_chapters(self):\n        text = (\n            "第一章 风起\\n" + "这里是第一章正文。" * 10 +\n            "\\n\\n第二章 云涌\\n" + "这里是第二章正文。" * 10\n        )\n\n        response = self.client.post(\n            f"{API_PREFIX}/import/project-file",\n            files={"file": ("批量导入.txt", text.encode("gb18030"), "text/plain")},\n        )\n\n        self.assertEqual(response.status_code, 200)\n        data = response.json()["data"]\n        self.assertEqual(data["encoding"], "GB18030")\n        self.assertEqual(data["total"], 2)\n        project_id = data["project_id"]\n\n        db = SessionLocal()\n        try:\n            project = db.query(Project).filter(Project.id == project_id).one_or_none()\n            chapters = (\n                db.query(Chapter)\n                .filter(Chapter.project_id == project_id)\n                .order_by(Chapter.sort_order.asc())\n                .all()\n            )\n            self.assertIsNotNone(project)\n            self.assertEqual(project.title, "批量导入")\n            self.assertEqual(len(chapters), 2)\n            self.assertEqual([chapter.sort_order for chapter in chapters], [1000, 2000])\n        finally:\n            db.close()\n\n    def test_import_preview_uses_regex_chapter_boundaries_without_llm(self):\n')

siming_app_path = "mobile/android/app/src/main/java/com/siming/mobile/ui/SimingApp.kt"
siming_app = read(siming_app_path)
needle = "onPickText: (((String, String) -> Unit) -> Unit)"
count = siming_app.count(needle)
if count != 2:
    raise RuntimeError(f"SimingApp.kt: expected 2 callback type matches, found {count}")
siming_app = siming_app.replace(
    needle,
    "onPickText: (((MobileNovelImportFile) -> Unit) -> Unit)",
)
old_callback = """                        onPickText { name, text ->
                            viewModel.importNovel(name, text, onOpenProject)
                        }
"""
new_callback = """                        onPickText { file ->
                            viewModel.importNovel(file, onOpenProject)
                        }
"""
if siming_app.count(old_callback) != 1:
    raise RuntimeError("SimingApp.kt: import callback shape changed")
siming_app = siming_app.replace(old_callback, new_callback, 1)
write(siming_app_path, siming_app)

print("Android TXT batch import patch applied.")
